34: public abstract class AbstractParser implements CustomParser {
35: 
36:     /** The current submodes of this parser */
37:     protected Submodes submodes = new Submodes();
38: 
39:     /**
40:      * The current language of this parser. Used to decide whether and how to
41:      * use the CJKSegmenter
42:      */
43:     protected Language language = Language.UNKNOWN;
44: 
45:     /** The IndexFacts.Session of this query */
46:     protected IndexFacts.Session indexFacts;
47: 
48:     protected String defaultIndex;
49: 
50:     /**
51:      * The counter for braces in URLs, braces in URLs are accepted so long as
52:      * they are balanced.
53:      */
54:     protected int braceLevelURL = 0;
55: 
56:     protected final ParserEnvironment environment;
57:     protected final TokenPosition tokens = new TokenPosition();
58: 
59:     /**
60:      * An enumeration of the parser index-controlled submodes. Any combination
61:      * of these may be active at the same time. SubModes are activated or
62:      * deactivated by specifying special indexes in the query.
63:      */
64:     static final class Submodes {
65: 
66:         /**
67:          * Url mode allows "_" and "-" as word characters. Default is false
68:          */
69:         public boolean url = false;
70: 
71:         /**
72:          * Site mode - host names get start of host and end of host markers.
73:          * Default is false
74:          */
75:         public boolean site = false;
76: 
77:         /**
78:          * Sets submodes from an index.
79:          *
80:          * @param indexName the index name which should decide the submodes, or null to do nothing.
81:          * @param session the session used to look up information about this index
82:          */
83:         // To avoid this we need to pass an IndexFacts.session down instead - easily done but not without breaking API's
84:         public void setFromIndex(String indexName, IndexFacts.Session session) {
85:             if (indexName == null) return;
86: 
87:             reset();
88:             Index current = session.getIndex(indexName);
89: 
90:             if (current.isUriIndex())
91:                 url = true;
92:             else if (current.isHostIndex())
93:                 site = true;
94:         }
95: 
96:         /** Sets default values for all submodes */
97:         public void reset() {
98:             url = false;
99:             site = false;
100:         }
101: 
102:         /**
103:          * Returns whether we are in a mode which allows explicit anchoring markers, ^ and $
104:          */
105:         public boolean explicitAnchoring() { return site; }
106: 
107:     }
