109:     /**
110:      * Creates a new instance of this class, storing the given {@link ParserEnvironment} for parse-time access to the
111:      * environment.
112:      *
113:      * @param environment the environment settings to attach to the Parser
114:      */
115:     protected AbstractParser(ParserEnvironment environment) {
116:         this.environment = ParserEnvironment.fromParserEnvironment(environment);
117:         if (this.environment.getIndexFacts() == null) {
118:             this.environment.setIndexFacts(new IndexFacts());
119:         }
120:     }
