122:     // TODO: Deprecate the unwanted method signatures below
123:     
124:     @Override
125:     public final QueryTree parse(Parsable query) {
126:         Item root = null;
127:         if (query != null) {
128:             root = parse(query.getQuery(),
129:                          query.getFilter(),
130:                          query.getExplicitLanguage().orElse(query.getLanguage()),
131:                          environment.getIndexFacts().newSession(query.getSources(), query.getRestrict()),
132:                          query.getDefaultIndexName(),
133:                          query);
134:         }
135:         if (root == null) {
136:             root = new NullItem();
137:         }
138:         return new QueryTree(root);
139:     }
140: 
141:     @Override
142:     public final Item parse(String queryToParse, String filterToParse, Language parsingLanguage,
143:                             IndexFacts.Session indexFacts, String defaultIndex) {
144:         return parse(queryToParse, filterToParse, parsingLanguage, indexFacts, defaultIndex, null);
145:     }
146: 
147:     Item parse(String queryToParse, String filterToParse, Language parsingLanguage,
148:                IndexFacts.Session indexFacts, String defaultIndex, Parsable parsable) {
149:         if (queryToParse == null) return null;
150: 
151:         if (defaultIndex != null)
152:             defaultIndex = indexFacts.getCanonicName(defaultIndex);
153: 
154:         tokenize(queryToParse, defaultIndex, indexFacts, parsingLanguage);
155: 
156:         if (parsingLanguage == null && parsable != null) {
157:             String detectionText = generateLanguageDetectionTextFrom(tokens, indexFacts, defaultIndex);
158:             if (detectionText.isEmpty()) // heuristic detection text extraction is fallible
159:                 detectionText = queryToParse;
160:             parsingLanguage = parsable.getOrDetectLanguage(detectionText);
161:         }
162: 
163:         setState(parsingLanguage, indexFacts, defaultIndex);
164:         Item root = parseItems();
165: 
166:         if (filterToParse != null) {
167:             AnyParser filterParser = new AnyParser(environment);
168:             if (root == null) {
169:                 root = filterParser.parseFilter(filterToParse, parsingLanguage, indexFacts);
170:             } else {
171:                 root = filterParser.applyFilter(root, filterToParse, parsingLanguage, indexFacts);
172:             }
173:         }
174:         if (defaultIndex != null)
175:             assignDefaultIndex(indexFacts.getCanonicName(defaultIndex), root);
176:         return simplifyPhrases(root);
177:     }
178: 
179:     /**
180:      * Do a best-effort attempt at creating a single string for language detection from only the relevant
181:      * subset of tokens. 
182:      * The relevant tokens are text tokens which follows names of indexes which are tokenized.
183:      * 
184:      * This method does not modify the position of the given token stream.
185:      */
186:     private String generateLanguageDetectionTextFrom(TokenPosition tokens, IndexFacts.Session indexFacts, String defaultIndex) {
187:         StringBuilder detectionText = new StringBuilder();
188:         int initialPosition = tokens.getPosition();
189:         while (tokens.hasNext()) { // look for occurrences of text and text:text
190:             while (!tokens.currentIs(Token.Kind.WORD) && tokens.hasNext()) // skip nonwords
191:                 tokens.next();
192:             if (!tokens.hasNext()) break;
193: 
194:             String queryText;
195:             Index index;
196: 
197:             Token word1 = tokens.next();
198:             if (is(Token.Kind.COLON, tokens.currentNoIgnore())) {
199:                 tokens.next(); // colon
200:                 Token word2 = tokens.next();
201:                 if ( is(Token.Kind.WORD, word2))
202:                     queryText = word2.image;
203:                 else
204:                     queryText = "";
205:                 index = indexFacts.getIndex(word1.image);
206:                 if (index.isNull()) { // interpret both as words
207:                     index = indexFacts.getIndex(defaultIndex);
208:                     queryText = word1.image + " " + queryText;
209:                 }
210:             } else if (is(Token.Kind.COLON, tokens.currentNoIgnore()) && is(Token.Kind.QUOTE, tokens.currentNoIgnore(1))) {
211:                 tokens.next(); // colon
212:                 tokens.next(); // quote
213:                 StringBuilder quotedContent = new StringBuilder();
214:                 while (!tokens.currentIs(Token.Kind.QUOTE) && tokens.hasNext()) {
215:                     Token token = tokens.next();
216:                     if (is(Token.Kind.WORD, token))
217:                         quotedContent.append(token.image).append(" ");
218:                 }
219:                 tokens.next();
220:                 queryText = quotedContent.toString();
221:                 index = indexFacts.getIndex(word1.image);
222:                 if (index.isNull()) { // interpret both as words
223:                     index = indexFacts.getIndex(defaultIndex);
224:                     queryText = word1.image + " " + queryText;
225:                 }
226:             } else {
227:                 index = indexFacts.getIndex(defaultIndex);
228:                 queryText = word1.image;
229:             }
230: 
231:             if (queryText != null && index.hasPlainTokens())
232:                 detectionText.append(queryText).append(" ");
233:         }
234:         tokens.setPosition(initialPosition);
235:         return detectionText.toString();
236:     }
237: 
238:     /**
239:      * Assigns the default index to query terms having no default index.
240:      *
241:      * This will apply the default index to terms without it added through the filter parameter,
242:      * where setting defaultIndex into state causes incorrect parsing.
243:      *
244:      * @param defaultIndex the default index to assign
245:      * @param item         the item to check
246:      */
247:     private static void assignDefaultIndex(String defaultIndex, Item item) {
248:         if (defaultIndex == null || item == null) return;
249: 
250:         if (item instanceof IndexedItem indexName) {
251:             if ("".equals(indexName.getIndexName()))
252:                 indexName.setIndexName(defaultIndex);
253:         }
254:         else if (item instanceof CompositeItem) {
255:             Iterator<Item> items = ((CompositeItem)item).getItemIterator();
256:             while (items.hasNext())
257:                 assignDefaultIndex(defaultIndex, items.next());
258:         }
259:     }
