268:     /**
269:      * Unicode normalizes some piece of natural language text. The chosen form
270:      * is compatibility decomposition, canonical composition (NFKC).
271:      */
272:     protected String normalize(String input) {
273:         if (input == null || input.length() == 0) return input;
274: 
275:         return environment.getLinguistics().getNormalizer().normalize(input);
276:     }
277: 
278:     protected void setState(Language queryLanguage, IndexFacts.Session indexFacts, String defaultIndex) {
279:         this.indexFacts = indexFacts;
280:         this.defaultIndex = defaultIndex;
281:         this.language = queryLanguage;
282:         this.submodes.reset();
283:     }
