285:     /**
286:      * Tokenizes the given string and initializes tokens with the found tokens.
287:      *
288:      * @param query            the string to tokenize
289:      * @param defaultIndexName the name of the index to use as default
290:      * @param indexFacts       resolved information about the index we are searching
291:      * @param language         the language set for this query, or null if none
292:      */
293:     protected void tokenize(String query, String defaultIndexName, IndexFacts.Session indexFacts, Language language) {
294:         Tokenizer tokenizer = new Tokenizer(environment.getLinguistics());
295:         tokenizer.setParserSettings(environment.getParserSettings());
296:         tokenizer.setSubstringSpecialTokens(language != null && language.isCjk());
297:         tokenizer.setSpecialTokens(environment.getSpecialTokens());
298:         tokens.initialize(tokenizer.tokenize(query, defaultIndexName, indexFacts));
299:     }
300: 
301:     /**
302:      * Collapses single item phrases in the tree to the contained item.
303:      *
304:      * @param unwashed The item whose phrases to simplify.
305:      * @return The simplified item.
306:      */
307:     public static Item simplifyPhrases(Item unwashed) {
308:         if (unwashed == null) {
309:             return unwashed;
310:         } else if (unwashed instanceof PhraseItem) {
311:             return collapsePhrase((PhraseItem) unwashed);
312:         } else if (unwashed instanceof CompositeItem composite) {
313:             ListIterator<Item> i = composite.getItemIterator();
314: 
315:             while (i.hasNext()) {
316:                 Item original = i.next();
317:                 Item transformed = simplifyPhrases(original);
318: 
319:                 if (original != transformed) {
320:                     i.set(transformed);
321:                 }
322:             }
323:             return unwashed;
324:         } else {
325:             return unwashed;
326:         }
327:     }
328: 
329:     private static Item collapsePhrase(PhraseItem phrase) {
330:         if (phrase.getItemCount() == 1 && phrase.getItem(0) instanceof WordItem word) {
331:             // TODO: Other stuff which needs propagation?
332:             word.setWeight(phrase.getWeight());
333:             return word;
334:         } else {
335:             return phrase;
336:         }
337:     }
338: 
339:     /**
340:      * Segments a token
341:      *
342:      * @param indexName the index name which preceded this token, or null if none
343:      * @param token the token to segment
344:      * @param quoted whether this segment is within quoted text
345:      * @return the resulting item
346:      */
347:     // TODO: The segmenting stuff is a mess now, this will fix it:
348:     // - Make Segmenter a class which is instantiated per parsing
349:     // - Make the instance know the language, etc and do all dispatching internally
350:     // -bratseth
351:     // TODO: Use segmenting for forced phrase searches?
352:     //
353:     // Language detection currently depends on tokenization (see generateLanguageDetectionTextFrom), but 
354:     // - the API's was originally not constructed for that, so a careful and somewhat unsatisfactory dance
355:     //   must be carried out to make it work
356:     // - it should really depend on parsing
357:     // This can be solved by making the segment method language independent by
358:     // always producing a query item containing the token text and resolve it to a WordItem or
359:     // SegmentItem after parsing and language detection.
360:     protected Item segment(String indexName, Token token, boolean quoted) {
361:         String normalizedToken = normalize(token.toString());
362: 
363:         if (token.isSpecial()) {
364:             WordItem w = new WordItem(token.toString(), true, token.substring);
365:             w.setWords(false);
366:             w.setFromSpecialToken(true);
367:             return w;
368:         }
369: 
370:         if (language == Language.UNKNOWN) {
371:             return new WordItem(normalizedToken, true, token.substring);
372:         }
373: 
374: 
375:         Segmenter segmenter = environment.getLinguistics().getSegmenter();
376:         List<String> segments = segmenter.segment(normalizedToken, language);
377:         if (segments.isEmpty()) {
378:             return null;
379:         }
380: 
381:         if (segments.size() == 1) {
382:             return new WordItem(segments.get(0), "", true, token.substring);
383:         }
384: 
385:         CompositeItem composite;
386:         if (indexFacts.getIndex(indexName).getPhraseSegmenting() || quoted) {
387:             composite = new PhraseSegmentItem(token.toString(), normalizedToken, true, false, token.substring);
388:         }
389:         else {
390:             composite = new AndSegmentItem(token.toString(), true, false);
391:         }
392:         int n = 0;
393:         WordItem previous = null;
394:         for (String segment : segments) {
395:             WordItem w = new WordItem(segment, "", true, token.substring);
396:             w.setFromSegmented(true);
397:             w.setSegmentIndex(n++);
398:             w.setStemmed(false);
399:             if (previous != null)
400:                 previous.setConnectivity(w, 1.0);
401:             previous = w;
402:             composite.addItem(w);
403:         }
404:         composite.lock();
405:         return composite;
406:     }
407: 
408:     /** Creates a new composite of the type specified in environment.getType().getComposite(). */
409:     protected CompositeItem newComposite() {
410:         return switch (environment.getType().getCompositeType()) {
411:             case and     -> new AndItem();
412:             case or      -> new OrItem();
413:             case phrase  -> new PhraseItem();
414:             case weakAnd -> new WeakAndItem();
415:         };
416:     }
417: 
418: }
