235:     @Test
236:     void testTimeout() {
237:         // yes, this test depends on numbers which have exact IEEE representations
238:         Query q = new Query(httpEncode("/search?timeout=500"));
239:         assertEquals(500000L, q.getTimeout());
240:         assertEquals(0, q.errors().size());
241: 
242:         q = new Query(httpEncode("/search?timeout=500 ms"));
243:         assertEquals(500, q.getTimeout());
244:         assertEquals(0, q.errors().size());
245: 
246:         q = new Query(httpEncode("/search?timeout=500.0ms"));
247:         assertEquals(500, q.getTimeout());
248:         assertEquals(0, q.errors().size());
249: 
250:         q = new Query(httpEncode("/search?timeout=500.0s"));
251:         assertEquals(500000, q.getTimeout());
252:         assertEquals(0, q.errors().size());
253: 
254:         q = new Query(httpEncode("/search?timeout=5ks"));
255:         assertEquals(5000000, q.getTimeout());
256:         assertEquals(0, q.errors().size());
257: 
258:         q = new Query(httpEncode("/search?timeout=5000.0 \u00B5s"));
259:         assertEquals(5, q.getTimeout());
260:         assertEquals(0, q.errors().size());
261: 
262:         // seconds is unit when unknown unit
263:         q = new Query(httpEncode("/search?timeout=42 yrs"));
264:         assertEquals(42000, q.getTimeout());
265:         assertEquals(0, q.errors().size());
266: 
267:         q = new Query();
268:         q.setTimeout(53L);
269:         assertEquals(53L, q.properties().get("timeout"));
270:         assertEquals(53L, q.getTimeout());
271: 
272:         // This is the unfortunate consequence of this legacy:
273:         q = new Query();
274:         q.properties().set("timeout", 53L);
275:         assertEquals(53L * 1000, q.properties().get("timeout"));
276:         assertEquals(53L * 1000, q.getTimeout());
