1387:     /**
1388:      * Url encode the given string, except the characters =?&, such that queries with paths and parameters can
1389:      * be written as a single string.
1390:      */
1391:     public static String httpEncode(String s) {
1392:         if (s == null) return null;
1393:         String encoded = URLEncoder.encode(s, StandardCharsets.UTF_8);
1394:         encoded = encoded.replaceAll("%3F", "?");
1395:         encoded = encoded.replaceAll("%3D", "=");
1396:         encoded = encoded.replaceAll("%26", "&");
1397:         return encoded;
1398:     }
